// Build a single text payload summarising this week's GitHub activity
// from the three upstream HTTP nodes' outputs. Drops PRs that are also
// issues (GitHub's PR API returns issues with a `pull_request` field).

const items = $input.all();
const byName = Object.fromEntries(items.map(i => [i.json.name ?? '?', i.json]));

const commitsResp = byName['Fetch Commits (last 7d)'] ?? {};
const issuesResp = byName['Fetch Closed Issues (last 7d)'] ?? {};
const prsResp = byName['Fetch Merged PRs (last 7d)'] ?? {};

const commits = Array.isArray(commitsResp) ? commitsResp : (commitsResp.body ? JSON.parse(commitsResp.body) : []);
const issues = Array.isArray(issuesResp) ? issuesResp : (issuesResp.body ? JSON.parse(issuesResp.body) : []);
const prs = Array.isArray(prsResp) ? prsResp : (prsResp.body ? JSON.parse(prsResp.body) : []);

const realIssues = issues.filter(i => !i.pull_request);
const mergedPrs = prs.filter(p => p.merged_at);

const commitLines = commits.slice(0, 50).map(c => `- ${(c.commit?.author?.name || c.commit?.author?.login || '?')}: ${(c.commit?.message || '').split('\n')[0]}`);
const issueLines = realIssues.slice(0, 30).map(i => `- [${i.state}] #${i.number} ${i.title}`);
const prLines = mergedPrs.slice(0, 30).map(p => `- merged #${p.number} ${p.title} (by @${p.user?.login || '?'})`);

const payload = [
  `Repository: ${$env.GITHUB_REPO}`,
  `Period: last 7 days (since ${$now.minus({ days: 7 }).toISO()})`,
  '',
  `Commits (${commits.length} total, showing up to 50):`,
  ...commitLines,
  '',
  `Closed issues (${realIssues.length} total, showing up to 30):`,
  ...issueLines,
  '',
  `Merged PRs (${mergedPrs.length} total, showing up to 30):`,
  ...prLines,
].join('\n');

return [{ json: { activity: payload, counts: { commits: commits.length, closedIssues: realIssues.length, mergedPrs: mergedPrs.length } } }];

