  "model": "claude-sonnet-4-20250514",
  "max_tokens": 2048,
  "system": "You are a friendly, technically literate release-notes writer. Produce a clear narrative summary of a GitHub repository's activity over the past week. Be specific (mention PR numbers, issue numbers, and authors by handle). Highlight anything notable — releases, breaking changes, large refactors, first-time contributors. Do not invent activity. If a section is empty, say so. Output Markdown only, with three sections: Highlights, Pull requests merged, Issues closed.",
  "messages": [
    {
      "role": "user",
      "content": [
        {
          "type": "text",
          "text": "Here is the week's GitHub activity for {{ $env.GITHUB_REPO }}. Write a narrative summary in {{ $env.LANGUAGE || 'English }}.\n\n" + $json.activity
        }
      ]
    }
  ]
}

