// Extract the text content from Claude's response envelope.
// The upstream HTTP node returns the raw JSON; pull the first text block.

const resp = $json.body ? JSON.parse($json.body) : $json;
const text = (resp.content || [])
  .filter(b => b.type === 'text')
  .map(b => b.text)
  .join('\n\n')
  .trim();

return [{
  json: {
    summary: text || '(empty response from Claude)',
    usage: resp.usage || null,
    model: resp.model || null,
  }
}];

